import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent implements OnInit {

  filtersForm!: FormGroup;

  @Output() filtersChanged = new EventEmitter<any>();

  constructor(private fb: FormBuilder) {}

  ngOnInit(): void {
    this.filtersForm = this.fb.group({
      searchText: [''],
      selectedCategory: [''],
      maxPrice: [5000],
      sortBy: ['']
    });

    // emit automatically when any filter changes
    this.filtersForm.valueChanges.subscribe(values => {
      this.emitFilters(values);
    });
  }

  applyFilters() {
    this.emitFilters(this.filtersForm.value);
  }

  private emitFilters(values: any) {
    this.filtersChanged.emit(values);
  }
}
<form [formGroup]="filtersForm" class="navbar-filters d-flex align-items-center gap-3">
  <!-- Search -->
  <input
    type="text"
    class="form-control"
    placeholder="Search products..."
    formControlName="searchText"

  />
  <!-- <button class="btn btn-primary" (click)="applyFilters()">Search</button> -->

  <!-- Category -->
  <select class="form-select" formControlName="selectedCategory">
    <option value="">All Categories</option>
    <option value="Electronics">Electronics</option>
    <option value="Clothing">Clothing</option>
    <option value="Books">Books</option>
    <option value="Home Appliances">Home Appliances</option>
  </select>

  <!-- Price -->
  Price:
  <input
    type="range"
    class="form-range"
    min="0"
    max="5000"
    step="100"
    formControlName="maxPrice"
  />
  <span>{{ filtersForm.get('maxPrice')?.value }}</span>

  <!-- Sort -->
  <label class="form-label fw-bold">Sort By</label>
  <select class="form-select" formControlName="sortBy">
    <option value="">Select</option>
    <option value="lowToHigh">Price: Low to High</option>
    <option value="highToLow">Price: High to Low</option>
    <option value="newest">Newest First</option>
  </select>

  <!-- Apply Filters -->
  <button type="button" class="btn btn-primary" (click)="applyFilters()">
    Apply Filters
  </button>
</form>
